// renderKeyConsiderationsSlide() — extracted from js/app.js into js/pages/ during the
// Round 18 restructure (loaded via a <script> tag in index.html before
// js/app.js; the function declaration is hoisted into global scope so
// app.js's HTML_SLIDES map can reference it regardless of load order).
//
// Round 72: migrated from 100%-hardcoded HTML to reading
// KEY_CONSIDERATIONS_DATA (js/slide-data/06-key-considerations.data.js,
// generated by tools/export_key_considerations.py from the source Excel
// workbook). Every number on this slide was validated against the real
// workbook before the migration — all 8 stat-panel figures and every
// numeric claim in the 5 bullets matched exactly — so this changed where
// the numbers come from, not what they say. The `data-count-from` values
// (21.6, 0, 240, 41) are animation start-points, a design constant, not
// derived from data, so they stay hardcoded here.
function computeKeyConsiderations(){
  const rows = CFG.rows;
  const n = rows.length;
  const commitment = rows.reduce((s, r) => s + (r.commitment || 0), 0);
  const paid = rows.reduce((s, r) => s + (r.paid || 0), 0);
  const dist = rows.reduce((s, r) => s + (r.dist || 0), 0);
  const nav = rows.reduce((s, r) => s + (r.nav || 0), 0);
  const tv = rows.reduce((s, r) => s + (r.total_value || 0), 0);
  const dpi = paid ? dist / paid : 0;
  const rvpi = paid ? nav / paid : 0;
  const tvpi = paid ? tv / paid : 0;
  const gps = {};
  const mgrNav = {};
  rows.forEach(r => {
    gps[r.manager] = 1;
    mgrNav[r.manager] = (mgrNav[r.manager] || 0) + (r.nav || 0);
  });
  const gpCount = Object.keys(gps).length;
  let maxMgr = 0;
  Object.keys(mgrNav).forEach(k => { if (mgrNav[k] > maxMgr) maxMgr = mgrNav[k]; });
  const maxMgrPct = nav ? maxMgr / nav * 100 : 0;
  const maxMgrCeil = Math.ceil(maxMgrPct);
  const windowNav = rows.filter(r => r.vintage_segment === '2016-2018' || r.vintage_segment === '2019-2021').reduce((s, r) => s + (r.nav || 0), 0);
  const windowPct = nav ? windowNav / nav * 100 : 0;
  const words = ['Zero','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten'];
  const windowWord = words[Math.max(0, Math.min(10, Math.round(windowPct / 10)))];
  const below1 = nav ? rows.filter(r => (r.tvpi || 0) < 1).reduce((s, r) => s + (r.nav || 0), 0) / nav * 100 : 0;
  const below1r = Math.round(below1 * 10) / 10;
  const unfunded = rows.reduce((s, r) => s + (r.unfunded || 0), 0);
  const unfundedFrac = unfundedPct(unfunded, commitment);
  const unfundedPctDisp = (unfundedFrac * 100).toFixed(1);
  const fundedRough = Math.round((1 - unfundedFrac) * 10) * 10;
  const avgGp = gpCount ? Math.round(nav / 1e6 / gpCount) : 0;
  return {
    stats: {
      totalCommitmentBn: Math.round(commitment / 1e9 * 10) / 10,
      aggregateNavBn: Math.round(nav / 1e9 * 10) / 10,
      distinctPositions: n,
      gpRelationships: gpCount,
      unfundedPct: unfundedPctDisp,
      dpi: dpi,
      rvpi: rvpi,
      tvpi: tvpi
    },
    points: [
      {num:'01', text:'The portfolio has almost fully paid back its investors at ' + dpi.toFixed(2) + 'x DPI and is ~' + fundedRough + '% funded, a combination that suits secondary buyers'},
      {num:'02', text:'Avg GP exposure is c.$' + avgGp + 'M, with no manager at more than ' + maxMgrCeil + '% of NAV. The portfolio scale and diversification supports broad buyer interest without creating outsized single-manager concentration'},
      {num:'03', text: windowWord + ' in every ten dollars of NAV sit in the 2016 – 2021 vintages, the window most secondary buyers target outside VC & growth'},
      {num:'04', text:'Only ' + below1r + '% of NAV is held in positions currently below a 1.0x TVPI, supporting a narrower bid-ask spread at a portfolio level'},
      {num:'05', text:'Buyer appetite will vary by strategy, asset maturity and residual value creation potential'}
    ],
    emphasis: [
      ['almost fully paid back its investors'],
      ['no manager at more than ' + maxMgrCeil + '% of NAV'],
      ['2016 – 2021 vintages'],
      [below1r + '% of NAV', 'below a 1.0x TVPI'],
      ['Buyer appetite will vary']
    ],
    excludedCount: CFG.excludedCount || 0
  };
}

function renderKeyConsiderationsSlide(){
  const D = computeKeyConsiderations();
  // Generated by tools/figma_to_html.py from the real Figma "Key portfolio
  // considerations" frame — node 1:629 in the same Design-file copy as the
  // other converted slides. See figma-export/slide-04-key-considerations.json and
  // figma-export/slide-04-key-considerations.raw.html.
  //
  // No new converter bugs here — this slide is entirely flat text/rectangles
  // (a numbered 5-point list on the left, a dark green stats panel on the
  // right) plus one Figma COMPONENT node wrapping the numbered list, which
  // figma_to_html.py's walk() already handled correctly (COMPONENT falls
  // through to the same "recurse into children, emit no box of its own"
  // branch as GROUP/INSTANCE — it has no fill/stroke of its own here anyway).
  //
  // Worth flagging: this slide's Figma numbers (≈$44.4bn total commitment,
  // ≈$24.8bn aggregate NAV, 363 positions, 103 GP relationships, 95% called,
  // 0.97x/0.59x/1.56x DPI/RVPI/TVPI) don't match the old
  // 04-key-portfolio-considerations.png export's numbers (≈$54.9bn, ≈$34.4bn,
  // 368, 105, 96%, 0.96x/0.65x/1.61x) or its prose (e.g. "Nearly a third of
  // NAV is managed by Polaris" vs. the Figma copy's "Avg GP exposure is
  // c.$241M..."). Same pattern as the Round 7 cover-title discrepancy — not
  // reconciled by guessing, the Figma frame is reproduced as-is on the
  // assumption it's the current/intended data, not the old PNG.
  //
  const commitBn = Math.round(D.stats.totalCommitmentBn);
  const navBn = Math.round(D.stats.aggregateNavBn);
  const pointsHtml = D.points.map((p, i) => `
    <div class="kcRow">
      <div class="kcNum">${p.num}</div>
      <div class="kcPoint">${kcEmphasize(p.text, i, D.emphasis)}</div>
    </div>`).join('');

  return `<div class="fig-slide" style="position:relative;width:1920px;height:1080px;background:#ffffff;overflow:hidden;">
  <div class="fig-text" data-fig-name="chrome-year" style="position:absolute;left:68.00px;top:64.00px;width:49.00px;height:24.00px;font-family:'Plus Jakarta Sans',sans-serif;font-weight:400;font-style:normal;font-size:19.00px;line-height:23.94px;letter-spacing:0.00px;color:#787878;text-align:left;white-space:pre;">2026</div>
  <div class="fig-box" data-fig-name="chrome-logo-box" style="position:absolute;left:1675.00px;top:58.00px;width:177.00px;height:44.00px;border:1.0px solid #0f0f0f;box-sizing:border-box;"></div>
  <div class="fig-text" data-fig-name="chrome-logo" style="position:absolute;left:1677.00px;top:69.00px;width:177.00px;height:24.00px;font-family:'Plus Jakarta Sans',sans-serif;font-weight:400;font-style:normal;font-size:19.00px;line-height:23.94px;letter-spacing:5.00px;color:#0f0f0f;text-align:center;white-space:pre;">TANGIBLE</div>
  <div class="fig-text" data-fig-name="chrome-footer" style="position:absolute;left:68.00px;top:982.00px;width:112.00px;height:24.00px;font-family:'Plus Jakarta Sans',sans-serif;font-weight:400;font-style:normal;font-size:19.00px;line-height:23.94px;letter-spacing:0.00px;color:#96ac9e;text-align:left;white-space:pre;">Confidential</div>
  <div class="fig-text" data-fig-name="chrome-page" style="position:absolute;left:1674.00px;top:982.00px;width:178.00px;height:24.00px;font-family:'Plus Jakarta Sans',sans-serif;font-weight:400;font-style:normal;font-size:19.00px;line-height:23.94px;letter-spacing:0.00px;color:#96ac9e;text-align:right;white-space:pre;">04</div>
  <div class="fig-text" data-fig-name="title" style="position:absolute;left:68.00px;top:136.00px;width:991.00px;height:71.00px;font-family:'Plus Jakarta Sans',sans-serif;font-weight:500;font-style:normal;font-size:56.00px;line-height:70.56px;letter-spacing:0.00px;color:#104130;text-align:left;white-space:pre;">Key portfolio considerations</div>
  <div class="fig-text" data-fig-name="footnote" style="position:absolute;left:212.00px;top:985.00px;width:1215.00px;height:24.00px;font-family:'Plus Jakarta Sans',sans-serif;font-weight:400;font-style:normal;font-size:19.00px;line-height:23.94px;letter-spacing:0.00px;color:#787878;text-align:left;white-space:pre;">*Data as of March 31, 2026, converted to USD at spot. Excludes ${D.excludedCount} positions with a stale or absent valuation date, or a nil or negative NAV.</div>
  <div class="kcBody">
  <div class="kcList">${pointsHtml}
  </div>
  <div class="kcSummary" data-action="portfolioSummary" role="button" tabindex="0" title="Open full portfolio source metrics" aria-label="Open portfolio source data">
    <div class="kcSummaryHead">Portfolio Summary <span class="kcSummaryHint">&gt; Click data to expand</span></div>
    <div class="kcCards">
      <div class="kcCard"><div class="kcCardVal" data-count-to="${commitBn}" data-count-from="22" data-count-prefix="~$" data-count-suffix="bn">~$${commitBn}bn</div><div class="kcCardLbl">Total Commitment*</div></div>
      <div class="kcCard"><div class="kcCardVal" data-count-to="${navBn}" data-count-from="0" data-count-prefix="~$" data-count-suffix="bn">~$${navBn}bn</div><div class="kcCardLbl">Total NAV*</div></div>
      <div class="kcCard"><div class="kcCardVal" data-count-to="${D.stats.distinctPositions}" data-count-from="240">${D.stats.distinctPositions}</div><div class="kcCardLbl">Positions</div></div>
      <div class="kcCard"><div class="kcCardVal" data-count-to="${D.stats.gpRelationships}" data-count-from="41">${D.stats.gpRelationships}</div><div class="kcCardLbl">GP relationships</div></div>
    </div>
    <div class="kcRatios">
      <div class="kcRatio"><div class="kcRatioVal">${D.stats.unfundedPct}%</div><div class="kcRatioLbl">Unfunded</div></div>
      <div class="kcRatio"><div class="kcRatioVal">${D.stats.dpi.toFixed(2)}x</div><div class="kcRatioLbl">DPI</div></div>
      <div class="kcRatio"><div class="kcRatioVal">${D.stats.rvpi.toFixed(2)}x</div><div class="kcRatioLbl">RVPI</div></div>
      <div class="kcRatio"><div class="kcRatioVal">${D.stats.tvpi.toFixed(2)}x</div><div class="kcRatioLbl">TVPI</div></div>
    </div>
  </div>
  </div>
</div>`;
}

function kcEmphasize(text, i, phrases){
  let out = esc(text);
  (phrases[i] || []).forEach(phrase => {
    out = out.replace(esc(phrase), '<span class="kcEm">' + esc(phrase) + '</span>');
  });
  return out;
}
